"""Exact integer/dyadic checks of exported quotient balls, without Arb decoding."""


def compare_dyadic(a,b):
    """Compare signed integers times powers of two, without Float64 conversion."""
    n,e=a;m,f=b
    if n==0:return (0>m)-(0<m)
    if m==0:return (n>0)-(n<0)
    if (n<0)!=(m<0):return -1 if n<0 else 1
    sign=-1 if n<0 else 1;n=abs(n);m=abs(m)
    top=n.bit_length()+e;other=m.bit_length()+f
    if top!=other:return sign*((top>other)-(top<other))
    base=min(e,f);left=n<<(e-base);right=m<<(f-base)
    return sign*((left>right)-(left<right))


def add_dyadic(a,b):
    n,e=a;m,f=b
    if not n:return b
    if not m:return a
    base=min(e,f);return (n<<(e-base))+(m<<(f-base)),base


def parse_ball(encoded,*,maximum_midpoint_bits=2048):
    if encoded is None:return 0,0,0,0
    if not isinstance(encoded,list) or len(encoded)!=2 or any(not isinstance(v,list) or len(v)!=2 for v in encoded):
        raise ValueError('Malformed dyadic ball record')
    if any(not isinstance(v[0],str) or type(v[1]) is not int for v in encoded):
        raise ValueError('Noninteger dyadic mantissa/exponent encoding')
    mid=int(encoded[0][0],16);radius=int(encoded[1][0],16)
    if radius<0 or abs(mid).bit_length()>maximum_midpoint_bits:
        raise ValueError('Negative radius or midpoint exceeding declared export precision')
    return mid,encoded[0][1],radius,encoded[1][1]


def point_metric(encoded):
    m,e,r,_=parse_ball(encoded)
    if r!=0:raise ValueError('An exact encoded report metric is required')
    return m,e


def endpoints(ball):
    m,e,r,f=ball
    return add_dyadic((m,e),(-r,f)),add_dyadic((m,e),(r,f))


def interval_relation(first,second):
    alo,ahi=endpoints(first);blo,bhi=endpoints(second)
    overlap=compare_dyadic(alo,bhi)<=0 and compare_dyadic(blo,ahi)<=0
    ac=compare_dyadic(alo,blo)<=0 and compare_dyadic(ahi,bhi)>=0
    bc=compare_dyadic(blo,alo)<=0 and compare_dyadic(bhi,ahi)>=0
    kind=('equal' if ac and bc else 'first_contains_second' if ac else
          'second_contains_first' if bc else 'partial_overlap' if overlap else 'disjoint')
    return dict(kind=kind,overlap=overlap,first_contains_second=ac,second_contains_first=bc)


def ratio_floor_log2(numerator,denominator):
    n,e=numerator;d,f=denominator
    if n<=0 or d<=0:raise ValueError('Strictly positive dyadic ratio required')
    candidate=n.bit_length()+e-d.bit_length()-f
    return candidate if compare_dyadic((n,e),(d,f+candidate))>=0 else candidate-1


def row_metrics(encoded):
    maxmid=(0,0);maxrad=(0,0);minimum=None;exact_zero=0;exact_nonzero=0
    zero_midpoint_uncertainty=0;contains_zero=0;parsed=[]
    for record in encoded:
        ball=parse_ball(record);parsed.append(ball);m,e,r,f=ball
        absolute=(abs(m),e);radius=(r,f)
        if compare_dyadic(absolute,maxmid)>0:maxmid=absolute
        if compare_dyadic(radius,maxrad)>0:maxrad=radius
        contains_zero+=int(compare_dyadic(absolute,radius)<=0)
        if not r:
            if m:exact_nonzero+=1
            else:exact_zero+=1
        elif not m:zero_midpoint_uncertainty+=1
        else:
            value=ratio_floor_log2(absolute,radius)
            minimum=value if minimum is None else min(minimum,value)
    global_accuracy=(ratio_floor_log2(maxmid,maxrad) if maxmid[0] and maxrad[0] else None)
    return dict(maximum_absolute_midpoint=maxmid,maximum_radius=maxrad,
        minimum_finite_entry_floor_log2_abs_mid_over_radius=minimum,
        row_floor_log2_max_mid_over_max_radius=global_accuracy,
        exact_zero_entries=exact_zero,exact_nonzero_entries=exact_nonzero,
        zero_midpoint_with_positive_radius=zero_midpoint_uncertainty,
        entries_containing_zero=contains_zero),parsed


def check_report_metrics(metrics,diagnostic):
    maximum=metrics['maximum_absolute_midpoint'];radius=metrics['maximum_radius']
    expected_mid=point_metric(diagnostic['quotient_maximum_absolute_midpoint']['exact_ball'])
    expected_rad=point_metric(diagnostic['quotient_maximum_radius']['exact_ball'])
    if compare_dyadic(maximum,expected_mid)!=0 or compare_dyadic(radius,expected_rad)!=0:
        raise ValueError('Encoded row maximum disagrees with recorded exact report metric')
    ratio=diagnostic['quotient_max_radius_over_max_midpoint']
    if maximum[0]==0:
        if ratio is not None:raise ValueError('Undefined zero-midpoint ratio must not be reported as finite')
    else:
        if ratio is None:raise ValueError('A nonzero row midpoint needs its recorded radius ratio')
        upper=point_metric(ratio['exact_ball'])
        if upper[0]<0 or compare_dyadic((upper[0]*maximum[0],upper[1]+maximum[1]),radius)<0:
            raise ValueError('Recorded radius ratio is not an outward bound')
